# lab XP of level 5 (game.lab.xp_for_level(5) on 2026-11-11)
_LEVEL5_XP = 463


def calendar_for_early_players(apps, schema_editor):
    """«تقویم تازه‌وارد» for the players who are still under lab level 5 — most of them stopped
    in their first days; the calendar is a reason to come back."""
    User = apps.get_model("bio_lab", "User")
    User.objects.filter(lab_xp__lt=_LEVEL5_XP).update(newbie_eligible=True)


